local M = class("SimulateSelectRoleView",LikeOO.OOPopBase)
-- 侠客人生模拟器
M.m_uiName = "SimulateLift/SimulateSelectRole"  -- prefab name
M.m_size_type = 1
M.m_iphoneXAdapter = true

function M:onEnter()
    self:bindUI()
    self:refreshUI()
    self:showCloud()
end

function M:refreshUI()
    self:setTextByLanKey("text_resetCount", "simulateLeft_text_0005", self.m_model.m_resetCount)
    self:refreshQulityNode()
end

function M:showCloud(callBack)
    local fivelinesOpenAnim = ResourceUtil:LoadUIGameObject("FivelinesNew/FivelinesOpenAnim", Vector3.zero, nil)
    fivelinesOpenAnim.transform:SetParent(self.m_rootView.transform, false)
    self.m_control:setOnceTimer(1.5, function()
        UIUtil.destroyObject(fivelinesOpenAnim)
        if callBack then
            callBack()
        end
    end)
end

function M:refreshQulityNode()
    for index = 1, 3 do
        local itemData = self.m_model.m_itemDatas[index]
        local pageNode = self:findGameObject("roleQualityPage_"..index)
        local itemNodeLuaBehaviour = UIUtil.findLuaBehaviour(pageNode)
        if itemData and itemNodeLuaBehaviour then
            --品质背景
            self:showQualityEft(itemNodeLuaBehaviour,itemData.scoreLevel)
            local qualityImg = itemNodeLuaBehaviour:FindImage("img_qualityImg")
            GameUtil:updateResourcesImg(qualityImg, "Texture/simulateLift/".. itemData.bgName)
            local btn_qualityBtn = itemNodeLuaBehaviour:FindGameObject("btn_qualityBtn")
            UIUtil.setButtonClick(
                    btn_qualityBtn.transform,
                    function()
                        self:updateMsg("select_role",{roleId = itemData.roleId})
                    end
            )
            local nameList = string.cutText(itemData.name)
            LuaBehaviourUtil.setTextByLanKey(itemNodeLuaBehaviour, "text_name1", nameList[1] or "")
            LuaBehaviourUtil.setTextByLanKey(itemNodeLuaBehaviour, "text_name2", nameList[2] or "")
            LuaBehaviourUtil.setTextByLanKey(itemNodeLuaBehaviour, "text_name3", nameList[3] or "")
            LuaBehaviourUtil.setTextByLanKey(itemNodeLuaBehaviour, "text_name4", nameList[4] or "")
            for qulityIndex = 1, 4 do
                local qulityItemData = itemData.attribute[qulityIndex]
                local qulityItem = itemNodeLuaBehaviour:FindGameObject("itemNode_"..qulityIndex)
                local qulityItemLua = UIUtil.findLuaBehaviour(qulityItem)
                if qulityItemLua then
                    -- 设置颜色
                    LuaBehaviourUtil.setTextByLanKey(qulityItemLua, "text_qualityLevel", qulityItemData.levelName)
                    local qulityLevel_text = qulityItemLua:FindText("text_qualityLevel")
                    qulityLevel_text.color = Color(qulityItemData.color[1],qulityItemData.color[2], qulityItemData.color[3])
                    LuaBehaviourUtil.setTextByLanKey(qulityItemLua, "text_qualityName", qulityItemData.name)
                    LuaBehaviourUtil.setTextByLanKey(qulityItemLua, "text_qualityValue", qulityItemData.value)
                end
            end
        end
    end
end

function M:showQualityEft(itemNodeLuaBehaviour, scoreLevel)
    local m_roleQualityList = self.m_model.m_roleQualityList
    for index = 1, 5 do
        LuaBehaviourUtil.setObjectVisible(itemNodeLuaBehaviour, m_roleQualityList[index], scoreLevel == index)
        
    end
end

function M:bindUI()
    self:setTextByLanKey("text_selectText", self.m_model.m_open_id == 285 and  "simulateLeft_text_0031" or "simulateLeft_text_0069")
    self:setTextByLanKey("text_resetText", "simulateLeft_text_0006")
    self:setTextByLanKey("close_title_text", self.m_model.m_open_id == 285 and "simulateLeft_text_0030" or "simulateLeft_text_0068")
end

function M:destroy()
    M.super.destroy(self)
end

return M
